/* Large original cutout illustrations for homepage entrances. */
.entry-site .brand-entry-art.home-art-kids,.entry-site .brand-entry-art.home-art-stories{height:230px;padding:0;background-repeat:no-repeat;background-position:center;background-size:auto 96%}
.entry-site .brand-entry-art.home-art-kids{background-color:#edf2e3;background-image:url("data:image/png;base64,")}
.entry-site .brand-entry-art.home-art-stories{background-color:#f4eddf;background-image:url("data:image/png;base64,")}
.entry-site .brand-entry-art{height:230px}
.home-adult-hosts{display:flex;gap:12px;flex-wrap:wrap}.home-adult-hosts a{display:flex;flex-direction:column;align-items:center;gap:8px;color:#42664d;flex:1;font-size:18px;padding:12px 8px;background:#f1f3e7;border-radius:16px;min-width:84px;text-decoration:none}.home-adult-hosts img{width:68px;height:88px;object-fit:contain}
@media(max-width:760px){.entry-site .brand-entry-art,.entry-site .brand-entry-art.home-art-kids,.entry-site .brand-entry-art.home-art-stories{height:165px}.home-adult-hosts a{font-size:18px}}

